// Live H2 acceptance with real UI/API/PostgreSQL. Credentials arrive on stdin.
// OTPs are generated by PyOTP, not a physical authenticator app; manual app
// acceptance remains separate. No secret-bearing screenshots or trace output.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdir, writeFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";
const { chromium } = await import(process.env.ATLAS_PLAYWRIGHT_MODULE ? pathToFileURL(process.env.ATLAS_PLAYWRIGHT_MODULE).href : "playwright");
let input = "";
for await (const chunk of process.stdin) input += chunk;
const { email, password } = JSON.parse(input);
input = "";
const origin = process.env.ATLAS_BROWSER_BASE_URL || "http://127.0.0.1:3147";
const output = process.env.ATLAS_BROWSER_OUTPUT || "/tmp/atlas-h2-browser";
const python = process.env.ATLAS_TEST_PYTHON;
if (!python) throw new Error("ATLAS_TEST_PYTHON is required for ephemeral OTP generation");
const apiDirectory = process.env.ATLAS_TEST_API_DIRECTORY;
const lastSteps = new Map();
const sensitive = new Set([password]);
let stage = "launch";
const errors = [];
const external = [];
const browser = await chromium.launch({ executablePath: process.env.ATLAS_CHROME_PATH, headless: true });
await mkdir(output, { recursive: true });

async function otp(seed) {
  sensitive.add(seed);
  const previous = lastSteps.get(seed) ?? -1;
  while (Math.floor(Date.now() / 30000) <= previous) await new Promise(resolve => setTimeout(resolve, 500));
  const result = spawnSync(python, ["-c", "import sys,pyotp;print(pyotp.TOTP(sys.stdin.read()).now())"], { input: seed, encoding: "utf8" });
  if (result.status !== 0) throw new Error("Local test OTP generation failed");
  lastSteps.set(seed, Math.floor(Date.now() / 30000));
  const code = result.stdout.trim(); sensitive.add(code); return code;
}

try {
  const context = await browser.newContext();
  const page = await context.newPage();
  page.on("pageerror", () => errors.push(stage));
  page.on("request", request => { if (!request.url().startsWith(origin)) external.push(new URL(request.url()).origin); });
  const security = () => page.getByRole("region", { name: "Two-factor authentication", exact: true });

  async function passwordLogin() {
    if (new URL(page.url()).pathname !== "/login") await page.goto(`${origin}/login`);
    await page.getByLabel("Email", { exact: true }).fill(email);
    await page.getByLabel("Password", { exact: true }).fill(password);
    await page.getByRole("button", { name: "Sign in", exact: true }).click();
  }
  async function logout() {
    await page.getByRole("button", { name: /^Open user menu for / }).click();
    await page.getByRole("menuitem", { name: "Log out", exact: true }).click();
    await page.waitForURL("**/login");
    await page.getByLabel("Email", { exact: true }).waitFor();
  }
  async function recoveryLogin(code) {
    await passwordLogin();
    await page.getByRole("button", { name: "Use a recovery code", exact: true }).click();
    await page.getByLabel("Recovery code", { exact: true }).fill(code);
    await page.getByRole("button", { name: "Verify and sign in", exact: true }).click();
  }
  async function saveCodes() {
    const list = security().getByRole("list", { name: "Recovery codes", exact: true });
    await list.waitFor();
    const codes = await list.locator("code").allTextContents();
    codes.forEach(code => sensitive.add(code));
    assert.equal(codes.length, 12);
    await security().getByRole("button", { name: "I have saved my recovery codes", exact: true }).click();
    return codes;
  }
  async function enable() {
    stage = "enrollment profile";
    await page.goto(`${origin}/profile`);
    stage = "enrollment start";
    await security().getByRole("button", { name: "Enable two-factor authentication", exact: true }).click();
    stage = "enrollment password";
    await security().getByLabel("Current password", { exact: true }).fill(password);
    await security().getByRole("button", { name: "Continue", exact: true }).click();
    stage = "enrollment manual key";
    await security().getByLabel("Manual setup key", { exact: true }).waitFor();
    const secret = await security().getByLabel("Manual setup key", { exact: true }).inputValue();
    const canvas = security().getByRole("img");
    stage = "local QR pixels";
    await page.waitForFunction(() => {
      const element = document.querySelector('canvas[role="img"]');
      return element && element.width === 240;
    });
    assert.ok(await canvas.evaluate(element => {
      const bytes = element.getContext("2d").getImageData(0, 0, element.width, element.height).data;
      return element.width > 0 && bytes.some((value, index) => index % 4 !== 3 && value === 0);
    }));
    stage = "enrollment confirmation";
    await security().getByLabel("Authenticator code", { exact: true }).fill(await otp(secret));
    await security().getByRole("button", { name: "Confirm authenticator", exact: true }).click();
    stage = "enrollment recovery display";
    const codes = await saveCodes();
    assert.equal(await security().getByLabel("Manual setup key", { exact: true }).count(), 0);
    return { secret, codes };
  }

  stage = "normal login";
  await passwordLogin();
  await page.waitForURL("**/dashboard");
  stage = "enrollment and local QR";
  let { secret, codes } = await enable();
  for (const width of [1440, 1024, 800, 390]) {
    await page.setViewportSize({ width, height: 1000 });
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true);
    await page.screenshot({ path: `${output}/security-enabled-${width}.png`, fullPage: true });
  }
  stage = "theme and accent presentation";
  for (const appearance of [{ theme_mode: "light", accent_colour: "#2563EB" }, { theme_mode: "dark", accent_colour: "#7C3AED" }]) {
    const profile = await context.request.get(`${origin}/api/auth/me`);
    const current = await profile.json();
    const changed = await context.request.patch(`${origin}/api/auth/profile`, { data: { display_name: current.display_name, ...appearance } });
    assert.equal(changed.status(), 200);
    await page.reload();
    await security().getByRole("button", { name: "Replace authenticator", exact: true }).waitFor();
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true);
    await page.screenshot({ path: `${output}/security-${appearance.theme_mode}-390.png`, fullPage: true });
  }
  stage = "TOTP login and challenge isolation";
  await logout(); await passwordLogin();
  await page.getByRole("heading", { name: "Verify two-factor authentication", exact: true }).waitFor();
  assert.equal((await context.request.get(`${origin}/api/auth/me`)).status(), 401);
  const challenge = (await context.cookies()).find(cookie => cookie.name === "atlas_mfa");
  assert.equal(challenge.httpOnly, true); assert.equal(challenge.path, "/api/auth/mfa");
  assert.equal((await context.cookies()).some(cookie => cookie.name === "atlas_session"), false);
  await page.getByLabel("Authenticator code", { exact: true }).fill(await otp(secret));
  await page.getByRole("button", { name: "Verify and sign in", exact: true }).click();
  await page.waitForURL("**/dashboard");
  stage = "recovery login and replay rejection";
  await logout(); await recoveryLogin(codes[0]); await page.waitForURL("**/dashboard");
  await logout(); await recoveryLogin(codes[0]);
  await page.getByRole("alert").filter({ hasText: "Invalid or already used" }).waitFor();
  await page.getByLabel("Recovery code", { exact: true }).fill(codes[1]);
  await page.getByRole("button", { name: "Verify and sign in", exact: true }).click();
  await page.waitForURL("**/dashboard");
  stage = "recovery regeneration";
  await page.goto(`${origin}/profile`);
  await security().getByRole("button", { name: "Generate new recovery codes", exact: true }).click();
  await security().getByLabel("Current password", { exact: true }).fill(password);
  await security().getByLabel("Authenticator code", { exact: true }).fill(await otp(secret));
  await security().getByRole("button", { name: "Continue", exact: true }).click();
  const oldCode = codes[2]; codes = await saveCodes();
  await logout(); await recoveryLogin(oldCode);
  await page.getByRole("alert").filter({ hasText: "Invalid or already used" }).waitFor();
  await page.getByLabel("Recovery code", { exact: true }).fill(codes[0]);
  await page.getByRole("button", { name: "Verify and sign in", exact: true }).click();
  await page.waitForURL("**/dashboard");
  stage = "replacement";
  await page.goto(`${origin}/profile`);
  await security().getByRole("button", { name: "Replace authenticator", exact: true }).click();
  await security().getByLabel("Current password", { exact: true }).fill(password);
  await security().getByLabel("Authenticator code", { exact: true }).fill(await otp(secret));
  await security().getByRole("button", { name: "Continue", exact: true }).click();
  const replacedSecret = await security().getByLabel("Manual setup key", { exact: true }).inputValue();
  assert.notEqual(replacedSecret, secret);
  await security().getByLabel("Authenticator code", { exact: true }).fill(await otp(replacedSecret));
  await security().getByRole("button", { name: "Confirm authenticator", exact: true }).click();
  codes = await saveCodes(); secret = replacedSecret;
  stage = "self disable";
  await security().getByRole("button", { name: "Disable two-factor authentication", exact: true }).click();
  await security().getByLabel("Current password", { exact: true }).fill(password);
  await security().getByRole("button", { name: "Use a recovery code", exact: true }).click();
  await security().getByLabel("Recovery code", { exact: true }).fill(codes[0]);
  await security().getByRole("button", { name: "Disable two-factor authentication", exact: true }).click();
  await security().getByRole("button", { name: "Enable two-factor authentication", exact: true }).waitFor();
  stage = "local break-glass command";
  ({ secret, codes } = await enable());
  const originalCodes = codes;
  await logout(); await recoveryLogin(codes[0]); await page.waitForURL("**/dashboard");
  const reset = spawnSync(python, ["-m", "scripts.mfa", "reset", "--user", email], {
    cwd: apiDirectory, input: "RESET\n", encoding: "utf8", env: process.env,
  });
  assert.equal(reset.status, 0);
  assert.match(reset.stdout, /Password unchanged/);
  await page.goto(`${origin}/login`);
  await passwordLogin(); await page.waitForURL("**/dashboard");
  assert.equal((await context.request.post(`${origin}/api/auth/mfa/verify`, { data: { code: originalCodes[1], method: "recovery" } })).status(), 401);
  const audit = await context.request.get(`${origin}/api/audit-events`);
  assert.equal(audit.status(), 200);
  assert.ok((await audit.json()).some(event => event.action === "auth.mfa_local_reset" || event.event_type === "auth.mfa_local_reset"));
  const storage = await page.evaluate(() => JSON.stringify([localStorage, sessionStorage]));
  assert.ok(!storage.includes(secret) && originalCodes.every(code => !storage.includes(code)));
  assert.ok(!storage.includes("atlas_mfa"));
  assert.deepEqual(errors, []); assert.deepEqual(external, []);
  await context.close();
  await writeFile(`${output}/report.json`, JSON.stringify({ result: "passed", liveAuthentication: true,
    physicalAuthenticator: false, localQr: true, widths: [1440, 1024, 800, 390], localCommand: true,
    dockerCommand: false, errors, externalRequests: external }, null, 2));
  console.log("PASS: live MFA enrollment, login, recovery, regeneration, replacement, disable and local break-glass.");
} catch (error) {
  let reason = String(error.message).split("\n")[0];
  for (const value of sensitive) reason = reason.replaceAll(value, "[redacted]");
  console.error(`FAIL: live MFA acceptance at ${stage} (${error.name}): ${reason.slice(0, 200)}. Page content omitted.`);
  process.exitCode = 1;
} finally { await browser.close(); }
